import { Network } from "../models/Networks";
import { KnownChains } from "../models/Chain";
export default class StringHelpers {
    static capitalizeFirstChar(str) {
        return str[0].toUpperCase() + str.slice(1).toLowerCase();
    }
    static stringToChain(chain) {
        if (!Object.values(KnownChains).includes(chain)) {
            throw new Error(`Invalid chain id: ${chain}`);
        }
        return chain;
    }
    static getChainId(chain) {
        const [/* namespace */ , chainId] = chain.split(":");
        return parseInt(chainId, 10);
    }
    static networkToEthereum(network) {
        return network === Network.Mainnet ? "mainnet" : "sepolia";
    }
    static stripHexPrefix(value) {
        return StringHelpers.isHexPrefixed(value) ? value.slice(2) : value;
    }
    static addHexPrefix(value) {
        return StringHelpers.isHexPrefixed(value) ? value : `0x${value}`;
    }
    static isHexPrefixed(str) {
        if (typeof str !== "string") {
            throw new Error(`[isHexPrefixed] input must be type "string", received type ${typeof str}`);
        }
        return str.slice(0, 2) === "0x";
    }
    static pathArrayToString(path) {
        return `m/${path.join("'/")}`;
    }
}
