export default class ContractServiceContext {
    constructor(strategy) {
        this.strategy = strategy;
    }
    contractCallFunction(contractAddress, functionName, paramsEncoded, gas, usePaymaster) {
        return this.strategy.contractCallFunction(contractAddress, functionName, paramsEncoded, gas, usePaymaster);
    }
    contractCallQueryFunction(contractAddress, functionName, paramsEncoded, gas, usePaymaster, resultTypes) {
        return this.strategy.contractCallQueryFunction(contractAddress, functionName, paramsEncoded, gas, usePaymaster, resultTypes);
    }
}
