export default class AbstractServiceEthereum {
    constructor(chain) {
        this.chain = chain;
    }
    get signer() {
        if (!this.container) {
            throw new Error(`Container not set in ${this.constructor.name} class`);
        }
        const user = this.container.get("user");
        if (!user || !user.signer) {
            throw new Error("No Signer found. Call setUser() first");
        }
        return user.signer;
    }
}
