export default class TokenServiceContext {
    constructor(strategy) {
        this.strategy = strategy;
    }
    getBalance(accountId) {
        return this.strategy.getBalance(accountId);
    }
    transferBalance(transferData) {
        return this.strategy.transferBalance(transferData);
    }
    transferToken(transferData) {
        return this.strategy.transferToken(transferData);
    }
    associateToken(tokenId, accountId) {
        return this.strategy.associateToken(tokenId, accountId);
    }
    createToken(tokenName, tokenSymbol, isNft, treasuryAccountId, supplyPublicKey, keys, decimals, initialSupply, maxSupply) {
        return this.strategy.createToken(tokenName, tokenSymbol, isNft, treasuryAccountId, supplyPublicKey, keys, decimals, initialSupply, maxSupply);
    }
    nftMint(tokenId, file, metadata, storageConfig) {
        return this.strategy.nftMint(tokenId, file, metadata, storageConfig);
    }
    dropTokens(accountId, secretNonce) {
        return this.strategy.dropTokens(accountId, secretNonce);
    }
    swapTokens(accountAddress, selectedQuote, txData) {
        return this.strategy.swapTokens(accountAddress, selectedQuote, txData);
    }
}
